insert into variety_master ("tenant_id", "key", "name", "crop_key", "code", "seed_source", "maturity", "calibration", "seasons_of_history", "note") values
  ('demo', 'kufri_pukhraj', 'Kufri Pukhraj', 'potato', 'VAR-POT-001', 'Own multiplication', 'Early, 90 to 100 days', 'Calibrated, 3 seasons', 3, 'The workhorse variety. Table and seed lots are tracked separately below it.'),
  ('demo', 'kufri_jyoti', 'Kufri Jyoti', 'potato', 'VAR-POT-002', 'Own multiplication', 'Medium, 100 to 110 days', 'Calibrated, 3 seasons', 3, null),
  ('demo', 'kufri_chipsona_1', 'Kufri Chipsona-1', 'potato', 'VAR-POT-003', 'Certified purchase', 'Medium, 100 to 110 days', 'Calibrated, 3 seasons', 3, 'Processing variety with the best grade record in the book: 88 percent chips grade A in West Bengal.'),
  ('demo', 'lady_rosetta', 'Lady Rosetta', 'potato', 'VAR-POT-004', 'Imported certified', 'Early, 85 to 95 days', 'Calibrated, 2 seasons', 2, 'Ran 14.4 percent under expected yield and only 58 percent chips grade A. Both failures trace to heat during bulking, not to two separate problems.'),
  ('demo', 'santana', 'Santana', 'potato', 'VAR-POT-005', 'Imported certified', 'Medium, 95 to 105 days', 'Base model, 1 season', 1, 'One season of history. Sits on the base model, so the 6.8 percent gap is not yet evidence of anything.'),
  ('demo', 'kufri_bahar', 'Kufri Bahar', 'potato', 'VAR-POT-006', 'Own multiplication', 'Late, 110 to 120 days', 'Base model, 1 season', 1, 'The smallest variety in the book and the only one reading above expectation. On one season of history that is noise, not performance.'),
  ('demo', 'hd_2967', 'HD 2967', 'wheat', 'VAR-WHT-001', 'Certified purchase', 'Medium, 140 to 150 days', 'Calibrated, 3 seasons', 3, null),
  ('demo', 'hd_3086', 'HD 3086', 'wheat', 'VAR-WHT-002', 'Certified purchase', 'Medium, 140 to 150 days', 'Calibrated, 3 seasons', 3, null),
  ('demo', 'pbw_725', 'PBW 725', 'wheat', 'VAR-WHT-003', 'Certified purchase', 'Late sown, 130 to 140 days', 'Calibrated, 2 seasons', 2, 'Grown deliberately late, after paddy harvest. The stage set is the standard wheat one, which is why grain filling reads short here.'),
  ('demo', 'durum_sharbati', 'Durum Sharbati', 'wheat', 'VAR-WHT-004', 'Own multiplication', 'Medium, 135 to 145 days', 'Base model, 1 season', 1, null),
  ('demo', 'pusa_basmati_1121', 'Pusa Basmati 1121', 'paddy', 'VAR-PDY-001', 'Certified purchase', 'Long, 140 to 145 days', 'Calibrated, 2 seasons', 2, null),
  ('demo', 'pusa_basmati_1509', 'Pusa Basmati 1509', 'paddy', 'VAR-PDY-002', 'Certified purchase', 'Short, 115 to 120 days', 'Calibrated, 2 seasons', 2, null),
  ('demo', 'swarna', 'Swarna', 'paddy', 'VAR-PDY-003', 'Truthful label', 'Long, 145 to 150 days', 'Calibrated, 2 seasons', 2, null),
  ('demo', 'ir_64', 'IR 64', 'paddy', 'VAR-PDY-004', 'Truthful label', 'Medium, 125 to 130 days', 'Base model, 1 season', 1, null),
  ('demo', 'abhinav', 'Abhinav', 'tomato', 'VAR-TOM-001', 'Hybrid purchase', 'Medium, 135 to 145 days', 'Calibrated, 2 seasons', 2, null),
  ('demo', 'namdhari_585', 'Namdhari 585', 'tomato', 'VAR-TOM-002', 'Hybrid purchase', 'Medium, 135 to 145 days', 'Calibrated, 2 seasons', 2, 'Part of the book runs under protected cultivation, which is why it carries an annual season alongside kharif and rabi.'),
  ('demo', 'heemsohna', 'Heemsohna', 'tomato', 'VAR-TOM-003', 'Hybrid purchase', 'Early, 120 to 130 days', 'Base model, 1 season', 1, 'No disease has been recorded against it yet. That is a reporting gap, not a resistant variety.'),
  ('demo', 'byadgi_dabbi', 'Byadgi Dabbi', 'chilli', 'VAR-CHL-001', 'Own selection', 'Long, 175 to 185 days', 'Base model, 1 season', 1, null),
  ('demo', 'teja_s17', 'Teja S17', 'chilli', 'VAR-CHL-002', 'Certified purchase', 'Medium, 165 to 175 days', 'Base model, 1 season', 1, null),
  ('demo', 'sankeshwar_32', 'Sankeshwar 32', 'chilli', 'VAR-CHL-003', 'Own selection', 'Long, 175 to 185 days', 'Base model, 1 season', 1, null),
  ('demo', 'pioneer_3396', 'Pioneer 3396', 'maize', 'VAR-MZE-001', 'Hybrid purchase', 'Medium, 110 to 120 days', 'Base model, 1 season', 1, null),
  ('demo', 'dkc_9144', 'DKC 9144', 'maize', 'VAR-MZE-002', 'Hybrid purchase', 'Medium, 110 to 120 days', 'Base model, 1 season', 1, null);
