insert into crop_target_dates ("tenant_id", "key", "crop_key", "region_key", "season_key", "ideal_window", "outer_window", "cost_of_breach") values
  ('demo', 'sw_potato_gujarat_rabi', 'potato', 'gujarat', 'rabi', '20 Oct to 10 Nov', '10 Oct to 25 Nov', 'Each week late costs about 0.9 t/ha, because bulking is pushed into February heat'),
  ('demo', 'sw_potato_uttar_pradesh_rabi', 'potato', 'uttar_pradesh', 'rabi', '25 Oct to 15 Nov', '15 Oct to 30 Nov', 'Each week late costs about 0.6 t/ha'),
  ('demo', 'sw_potato_west_bengal_rabi', 'potato', 'west_bengal', 'rabi', '05 Nov to 25 Nov', '28 Oct to 05 Dec', 'Sowing before the window raises late blight exposure sharply'),
  ('demo', 'sw_potato_punjab_rabi', 'potato', 'punjab', 'rabi', '15 Oct to 05 Nov', '05 Oct to 20 Nov', 'Each week late costs about 0.7 t/ha'),
  ('demo', 'sw_wheat_punjab_rabi', 'wheat', 'punjab', 'rabi', '01 Nov to 20 Nov', '25 Oct to 30 Nov', 'Each week past 30 Nov costs roughly 0.15 t/ha to terminal heat'),
  ('demo', 'sw_wheat_haryana_rabi', 'wheat', 'haryana', 'rabi', '05 Nov to 25 Nov', '28 Oct to 05 Dec', 'Each week past the window costs roughly 0.14 t/ha'),
  ('demo', 'sw_wheat_madhya_pradesh_rabi', 'wheat', 'madhya_pradesh', 'rabi', '10 Nov to 30 Nov', '01 Nov to 10 Dec', 'Grain filling collapses on late sowing here; observed 20 percent short'),
  ('demo', 'sw_paddy_punjab_kharif', 'paddy', 'punjab', 'kharif', '20 Jun to 10 Jul', '10 Jun to 20 Jul', 'Early transplanting breaches the state water calendar'),
  ('demo', 'sw_paddy_haryana_kharif', 'paddy', 'haryana', 'kharif', '25 Jun to 15 Jul', '15 Jun to 25 Jul', 'Late transplanting runs grain filling into cool nights'),
  ('demo', 'sw_paddy_west_bengal_kharif', 'paddy', 'west_bengal', 'kharif', '15 Jun to 05 Jul', '05 Jun to 15 Jul', 'Late transplanting collides with the flood window'),
  ('demo', 'sw_tomato_maharashtra_zaid', 'tomato', 'maharashtra', 'zaid', '01 Feb to 20 Feb', '25 Jan to 28 Feb', 'Fruit set moves into 38 C days and aborts; observed 11 percent yield gap'),
  ('demo', 'sw_tomato_karnataka_kharif', 'tomato', 'karnataka', 'kharif', '01 Jul to 20 Jul', '20 Jun to 31 Jul', 'Late planting raises leaf curl virus pressure'),
  ('demo', 'sw_chilli_karnataka_kharif', 'chilli', 'karnataka', 'kharif', '10 Jun to 30 Jun', '01 Jun to 10 Jul', 'Nursery raised late misses the first monsoon flush'),
  ('demo', 'sw_maize_madhya_pradesh_kharif', 'maize', 'madhya_pradesh', 'kharif', '20 Jun to 10 Jul', '10 Jun to 20 Jul', 'Tasselling in peak rain reduces pollination');
