insert into alert_master ("tenant_id", "key", "name", "kind", "crop_key", "category", "conditions", "symptoms", "advisory", "mitigation", "dews_model", "area_pct", "note") values
  ('demo', 'late_blight', 'Late Blight', 'disease', 'potato', 'Fungal disease', '10 to 24 C with relative humidity above 90 percent for 10 hours or more', 'Water soaked lesions on leaf margins, white sporulation on the underside, rapid collapse of the canopy', null, 'Preventive mancozeb, curative metalaxyl once lesions appear', 'DEWS model available, run daily on a 7 day forecast', null, null),
  ('demo', 'early_blight', 'Early Blight', 'disease', 'potato', 'Fungal disease', 'Warm 24 to 29 C with alternating wet and dry spells', 'Concentric dark rings on older leaves, defoliation from the base upward', null, 'Preventive mancozeb at tuber initiation', 'DEWS model available', null, null),
  ('demo', 'potato_tuber_moth', 'Potato Tuber Moth', 'disease', 'potato', 'Insect pest', 'Dry weather above 28 C, exposed tubers from poor earthing up', 'Tunnelling in tubers, frass at entry holes, damage found at grading', null, 'Pheromone traps at 8 per acre, earthing up, timely harvest', 'DEWS model available, degree day driven', null, null),
  ('demo', 'black_scurf', 'Black Scurf', 'disease', 'potato', 'Soil borne fungal disease', 'Cool wet soil at planting, infected seed', 'Black sclerotia on tuber skin, stem canker, uneven emergence', null, 'Seed treatment, avoid cold wet planting windows', 'No DEWS model. Managed through the sowing window instead', null, null),
  ('demo', 'yellow_rust', 'Yellow Rust', 'disease', 'wheat', 'Fungal disease', '10 to 18 C with dew on the leaf for 3 hours or more', 'Yellow pustules in stripes along the leaf veins', null, 'Preventive propiconazole at first report in the district', 'DEWS model available, best hit rate in the book at 88.9 percent', null, null),
  ('demo', 'karnal_bunt', 'Karnal Bunt', 'disease', 'wheat', 'Fungal disease', 'Cool humid weather at flowering, 18 to 24 C with rain', 'Partly bunted grain with a fishy odour, detected only at grading', null, 'Seed treatment and clean seed sourcing', 'DEWS model available but the weakest performer, 50 percent hit rate', null, null),
  ('demo', 'powdery_mildew_wheat', 'Powdery Mildew', 'disease', 'wheat', 'Fungal disease', '15 to 22 C with high humidity and dense canopy', 'White powdery growth on the upper leaf surface', null, 'Preventive sulphur or triazole spray', 'DEWS model available', null, null),
  ('demo', 'aphid_wheat', 'Wheat Aphid', 'disease', 'wheat', 'Insect pest', 'Mild 15 to 25 C, still weather after irrigation', 'Colonies on the ear and flag leaf, honeydew and sooty mould', null, 'Insecticide spray only above the economic threshold', 'No DEWS model', null, null),
  ('demo', 'bacterial_leaf_blight', 'Bacterial Leaf Blight', 'disease', 'paddy', 'Bacterial disease', '25 to 34 C with standing water and wind damage to leaves', 'Water soaked stripes turning straw yellow from the leaf tip', null, 'Balanced nitrogen, drain the field, copper based spray', 'DEWS model available. Flood triggered, so lead time is the shortest in the book at 1.4 days', null, null),
  ('demo', 'blast_rice', 'Rice Blast', 'disease', 'paddy', 'Fungal disease', 'Night temperature 20 to 26 C with long dew periods', 'Spindle shaped lesions with grey centres, neck rot at flowering', null, 'Preventive tricyclazole at panicle initiation', 'DEWS model available', null, null),
  ('demo', 'brown_plant_hopper', 'Brown Plant Hopper', 'disease', 'paddy', 'Insect pest', 'High humidity, dense canopy, excess nitrogen, continuous flooding', 'Hopper burn in circular patches, plants dry from the base', null, 'Alternate wetting and drying, avoid excess nitrogen, targeted insecticide', 'DEWS model available', null, null),
  ('demo', 'stem_borer_rice', 'Yellow Stem Borer', 'disease', 'paddy', 'Insect pest', 'Warm humid tillering period, staggered transplanting nearby', 'Dead hearts at tillering, white ears at flowering', null, 'Pheromone traps, clipping of egg masses at transplanting', 'DEWS model available', null, 'The mitigating activity, pheromone trap installation, is not in either paddy plan. Configured risk with no configured response.'),
  ('demo', 'early_blight_tomato', 'Early Blight', 'disease', 'tomato', 'Fungal disease', 'Warm wet weather 24 to 29 C, splash from overhead irrigation', 'Target spot lesions on lower leaves, stem collar rot in seedlings', null, 'Preventive mancozeb, switch from overhead to drip', 'DEWS model available', null, null),
  ('demo', 'tomato_leaf_curl_virus', 'Tomato Leaf Curl Virus', 'disease', 'tomato', 'Viral disease, whitefly vectored', 'Dry warm weather with high whitefly pressure', 'Upward curling and thickening of leaves, severe stunting, no fruit set', null, 'Vector control, barrier crops, resistant hybrids where available', 'No DEWS model. Vector pressure is not a weather variable the model reads', null, null),
  ('demo', 'fruit_borer_tomato', 'Fruit Borer', 'disease', 'tomato', 'Insect pest', 'Warm dry weather at fruit set', 'Circular bore holes in fruit, frass at the entry point', null, 'Pheromone traps, need based insecticide', 'DEWS model available', null, null),
  ('demo', 'thrips_chilli', 'Chilli Thrips', 'disease', 'chilli', 'Insect pest', 'Dry spells above 30 C, breaks in the monsoon', 'Upward leaf curl, silvering, flower drop, murda complex', null, 'Need based insecticide rotation, blue sticky traps', 'DEWS model available', null, null),
  ('demo', 'anthracnose_chilli', 'Anthracnose', 'disease', 'chilli', 'Fungal disease', 'Rain at fruit maturity, 25 to 30 C with wet fruit surfaces', 'Sunken circular lesions on ripening fruit, dieback of twigs', null, 'Preventive spray at fruit development, harvest ahead of rain', 'DEWS model available', null, null),
  ('demo', 'fall_armyworm', 'Fall Armyworm', 'disease', 'maize', 'Insect pest', 'Warm weather, staggered planting, continuous maize in the area', 'Ragged whorl feeding, sawdust like frass in the whorl', null, 'Early scouting, need based insecticide into the whorl', 'No DEWS model configured for this tenant yet', null, null),
  ('demo', 'hail', 'Hail', 'alert', null, 'Non biotic', 'Hail reported within the plot boundary during a convective event', null, 'Assess standing crop within 48 hours, photograph damage, notify insurer', null, null, 22.4, 'The costliest alert in the book at 22.4 percent mean area impacted, and no mitigating activity is configured against it.'),
  ('demo', 'frost', 'Frost', 'alert', null, 'Non biotic', 'Forecast minimum below 2 C for two consecutive nights', null, 'Light irrigation the evening before, smoke screens on the windward edge', null, null, 14.8, null),
  ('demo', 'drought_stress', 'Drought Stress', 'alert', null, 'Non biotic', 'Fourteen consecutive days with precipitation below 0.5 mm per day', null, 'Prioritise irrigation to critical stages, defer top dressing', null, null, 12.9, null),
  ('demo', 'waterlogging', 'Waterlogging', 'alert', null, 'Non biotic', 'Rainfall above 80 mm in 48 hours on a plot with poor drainage', null, 'Open drainage channels, defer nitrogen, watch for bacterial blight', null, null, 11.4, null),
  ('demo', 'heat_wave', 'Heat Wave', 'alert', null, 'Non biotic', 'Maximum above 38 C for three consecutive days', null, 'Irrigate to cool the canopy, avoid midday operations, expect grade loss', null, null, 9.6, null),
  ('demo', 'pest_outbreak_generic', 'Pest Outbreak', 'alert', null, 'Biotic', 'Pest incidence above 10 percent recorded on three neighbouring plots', null, 'Raise scouting frequency, prepare need based spray', null, null, 8.4, null),
  ('demo', 'unseasonal_rain', 'Unseasonal Rain', 'alert', null, 'Non biotic', 'Rainfall above 20 mm outside the expected seasonal pattern', null, 'Defer spraying and harvest, re-apply preventive fungicide after the rain', null, null, 7.2, null),
  ('demo', 'wind_damage', 'Wind Damage', 'alert', null, 'Non biotic', 'Wind speed above 45 km per hour during grain filling or fruiting', null, 'Inspect for lodging, plan early harvest of affected blocks', null, null, 6.1, null);
