insert into agg_stage_observation ("tenant_id", "key", "crop_key", "stage_key", "region_key", "season_key", "configured_days", "observed_days", "plots", "note") values
  ('demo', 'so_potato_bulking_gujarat', 'potato', 'pot_tuber_bulking', 'gujarat', 'rabi', 35, 32, 1180, 'Nine percent short. Activities anchored to the end of bulking fire after the crop has already finished bulking.'),
  ('demo', 'so_potato_bulking_uttar_pradesh', 'potato', 'pot_tuber_bulking', 'uttar_pradesh', 'rabi', 35, 38, 940, 'The same configured stage runs long here. One national stage set cannot serve both regions.'),
  ('demo', 'so_potato_initiation_gujarat', 'potato', 'pot_tuber_initiation', 'gujarat', 'rabi', 20, 19, 1180, null),
  ('demo', 'so_potato_vegetative_gujarat', 'potato', 'pot_vegetative', 'gujarat', 'rabi', 25, 23, 1140, null),
  ('demo', 'so_potato_maturation_west_bengal', 'potato', 'pot_maturation', 'west_bengal', 'rabi', 15, 17, 610, null),
  ('demo', 'so_wheat_tillering_punjab', 'wheat', 'wht_tillering', 'punjab', 'rabi', 30, 28, 2410, null),
  ('demo', 'so_wheat_grain_filling_punjab', 'wheat', 'wht_grain_filling', 'punjab', 'rabi', 30, 26, 2380, 'Terminal heat cuts grain filling short. The harvest window prediction is built on 30 days and reads late every season.'),
  ('demo', 'so_wheat_grain_filling_madhya_pradesh', 'wheat', 'wht_grain_filling', 'madhya_pradesh', 'rabi', 30, 24, 690, 'Twenty percent short, the largest deviation in the book.'),
  ('demo', 'so_paddy_tillering_punjab', 'paddy', 'pdy_tillering', 'punjab', 'kharif', 30, 31, 2210, null),
  ('demo', 'so_paddy_flowering_haryana', 'paddy', 'pdy_flowering', 'haryana', 'kharif', 15, 16, 1520, null),
  ('demo', 'so_paddy_grain_filling_west_bengal', 'paddy', 'pdy_grain_filling', 'west_bengal', 'kharif', 25, 27, 990, null),
  ('demo', 'so_tomato_fruit_development_maharashtra', 'tomato', 'tom_fruit_development', 'maharashtra', 'zaid', 30, 27, 760, null),
  ('demo', 'so_chilli_fruit_development_karnataka', 'chilli', 'chl_fruit_development', 'karnataka', 'kharif', 45, 49, 1130, null),
  ('demo', 'so_maize_grain_filling_madhya_pradesh', 'maize', 'mze_grain_filling', 'madhya_pradesh', 'kharif', 35, 33, 640, null);
insert into agg_season_outcome ("tenant_id", "key", "name", "crop_key", "variety_key", "region_key", "season_key", "rainfall", "mean_tmax", "heat_events", "expected", "achieved", "grade_outcome", "plots", "note") values
  ('demo', 'swo_rosetta_gujarat_rabi_2024', 'Lady Rosetta, Gujarat, Rabi 2024-25', 'potato', 'lady_rosetta', 'gujarat', 'rabi', '42 mm', '33.8 C', '6 days above 36 C during tuber bulking', 32, 27.4, '58 percent chips grade A, 42 percent of lots failed on dry matter', 720, 'The yield gap and the grade failure are the same event. Heat during bulking depressed both tonnage and dry matter, and they were reported as two separate problems.'),
  ('demo', 'swo_pukhraj_gujarat_rabi_2024', 'Kufri Pukhraj, Gujarat, Rabi 2024-25', 'potato', 'kufri_pukhraj', 'gujarat', 'rabi', '48 mm', '32.1 C', '2 days above 36 C during bulking', 28, 26.9, '81 percent table grade A', 1420, null),
  ('demo', 'swo_pukhraj_uttar_pradesh_rabi_2024', 'Kufri Pukhraj, Uttar Pradesh, Rabi 2024-25', 'potato', 'kufri_pukhraj', 'uttar_pradesh', 'rabi', '61 mm', '29.4 C', 'None', 28, 27.6, '84 percent table grade A', 1180, null),
  ('demo', 'swo_chipsona_west_bengal_rabi_2024', 'Kufri Chipsona-1, West Bengal, Rabi 2024-25', 'potato', 'kufri_chipsona_1', 'west_bengal', 'rabi', '88 mm', '28.6 C', 'None', 30, 29.8, '88 percent chips grade A', 610, 'The best grade outcome in the book, in the region with the highest disease pressure. Cool bulking beats everything else.'),
  ('demo', 'swo_jyoti_uttar_pradesh_rabi_2024', 'Kufri Jyoti, Uttar Pradesh, Rabi 2024-25', 'potato', 'kufri_jyoti', 'uttar_pradesh', 'rabi', '57 mm', '29.9 C', '1 day above 36 C', 25.5, 25.2, '86 percent in seed size', 940, null),
  ('demo', 'swo_hd2967_punjab_rabi_2024', 'HD 2967, Punjab, Rabi 2024-25', 'wheat', 'hd_2967', 'punjab', 'rabi', '96 mm', '31.2 C', '4 days above 35 C during grain filling', 5.4, 5.1, 'Mill grade 1 on 76 percent of lots', 2410, null),
  ('demo', 'swo_hd3086_haryana_rabi_2024', 'HD 3086, Haryana, Rabi 2024-25', 'wheat', 'hd_3086', 'haryana', 'rabi', '84 mm', '30.8 C', '2 days above 35 C', 5.6, 5.5, 'Mill grade 1 on 79 percent of lots', 1290, null),
  ('demo', 'swo_pb1121_punjab_kharif_2024', 'Pusa Basmati 1121, Punjab, Kharif 2024', 'paddy', 'pusa_basmati_1121', 'punjab', 'kharif', '612 mm', '34.1 C', 'None', 4.3, 4, 'Export grade on 68 percent of lots', 2210, null),
  ('demo', 'swo_pb1509_haryana_kharif_2024', 'Pusa Basmati 1509, Haryana, Kharif 2024', 'paddy', 'pusa_basmati_1509', 'haryana', 'kharif', '548 mm', '34.6 C', '1 dry spell of 11 days', 4.6, 4.5, 'Export grade on 71 percent of lots', 1520, null),
  ('demo', 'swo_swarna_west_bengal_kharif_2024', 'Swarna, West Bengal, Kharif 2024', 'paddy', 'swarna', 'west_bengal', 'kharif', '1,284 mm', '32.9 C', 'Waterlogging in 3 spells', 5.8, 5.4, 'Domestic grade', 990, 'Waterlogging, then bacterial leaf blight. The DEWS warning for it fired 1.4 days ahead, which was not enough to act on.'),
  ('demo', 'swo_abhinav_maharashtra_zaid_2025', 'Abhinav, Maharashtra, Zaid 2025', 'tomato', 'abhinav', 'maharashtra', 'zaid', '12 mm', '36.2 C', '9 days above 38 C at fruit set', 62, 55.1, '64 percent table grade A', 760, 'Fruit set ran into the heat wave window. The sowing window for this region and season exists to prevent exactly this.'),
  ('demo', 'swo_byadgi_karnataka_kharif_2024', 'Byadgi Dabbi, Karnataka, Kharif 2024', 'chilli', 'byadgi_dabbi', 'karnataka', 'kharif', '742 mm', '30.4 C', 'None', 2.8, 2.7, 'Colour value 126 ASTA, export grade on 82 percent', 1130, null);
insert into agg_dews_history ("tenant_id", "key", "name", "disease_key", "region_key", "season_key", "warnings", "critical", "followed", "hit_rate", "lead_days", "threshold", "note") values
  ('demo', 'dews_late_blight_gujarat_rabi', 'Late Blight, Gujarat, Rabi', 'late_blight', 'gujarat', 'rabi', 34, 12, 11, 91.7, 3.2, 75, null),
  ('demo', 'dews_late_blight_uttar_pradesh_rabi', 'Late Blight, Uttar Pradesh, Rabi', 'late_blight', 'uttar_pradesh', 'rabi', 41, 15, 12, 80, 2.9, 75, null),
  ('demo', 'dews_early_blight_gujarat_rabi', 'Early Blight, Gujarat, Rabi', 'early_blight', 'gujarat', 'rabi', 28, 9, 6, 66.7, 2.4, 75, null),
  ('demo', 'dews_tuber_moth_gujarat_rabi', 'Potato Tuber Moth, Gujarat, Rabi', 'potato_tuber_moth', 'gujarat', 'rabi', 19, 6, 5, 83.3, 5.8, 70, 'The best lead time in the book at 5.8 days, because the model is degree day driven rather than event driven. Five days is enough to get a sprayer or traps to the plot.'),
  ('demo', 'dews_yellow_rust_punjab_rabi', 'Yellow Rust, Punjab, Rabi', 'yellow_rust', 'punjab', 'rabi', 47, 18, 16, 88.9, 4.1, 75, null),
  ('demo', 'dews_karnal_bunt_haryana_rabi', 'Karnal Bunt, Haryana, Rabi', 'karnal_bunt', 'haryana', 'rabi', 22, 8, 4, 50, 2.2, 75, 'Half the critical warnings were followed by nothing. Raising the threshold would cut the noise but the disease is only detectable at grading, so a false positive is cheaper than a miss.'),
  ('demo', 'dews_blb_punjab_kharif', 'Bacterial Leaf Blight, Punjab, Kharif', 'bacterial_leaf_blight', 'punjab', 'kharif', 38, 14, 11, 78.6, 1.9, 75, null),
  ('demo', 'dews_blast_west_bengal_kharif', 'Rice Blast, West Bengal, Kharif', 'blast_rice', 'west_bengal', 'kharif', 52, 21, 17, 81, 2.6, 75, null),
  ('demo', 'dews_bph_punjab_kharif', 'Brown Plant Hopper, Punjab, Kharif', 'brown_plant_hopper', 'punjab', 'kharif', 31, 11, 9, 81.8, 3.4, 70, null),
  ('demo', 'dews_blb_west_bengal_kharif', 'Bacterial Leaf Blight, West Bengal, Kharif', 'bacterial_leaf_blight', 'west_bengal', 'kharif', 44, 16, 8, 50, 1.4, 75, 'Flood triggered, so the warning and the event arrive together. 1.4 days notice is only actionable where the drainage work is already planned.'),
  ('demo', 'dews_thrips_karnataka_kharif', 'Chilli Thrips, Karnataka, Kharif', 'thrips_chilli', 'karnataka', 'kharif', 26, 9, 7, 77.8, 4.6, 70, null),
  ('demo', 'dews_fruit_borer_maharashtra_zaid', 'Fruit Borer, Maharashtra, Zaid', 'fruit_borer_tomato', 'maharashtra', 'zaid', 24, 8, 6, 75, 3.9, 75, null);
